/// <summary>
/// Finds an environment by its id.
/// </summary>
/// <param name = "_environmentId">The environment id.</param>
/// <param name = "_forUpdate">true if the record is selected for update.</param>
/// <returns>The environment record; an empty buffer if it does not exist.</returns>
public static OLK_EnvironmentDataSetupTable find(OLK_EdsEnvironmentId _environmentId, boolean _forUpdate = false)
{
    OLK_EnvironmentDataSetupTable environment;

    if (_environmentId)
    {
        environment.selectForUpdate(_forUpdate);

        select firstonly environment
            where environment.EnvironmentId == _environmentId;
    }

    return environment;
}

/// <summary>
/// Checks whether an environment exists.
/// </summary>
/// <param name = "_environmentId">The environment id.</param>
/// <returns>true if the environment exists.</returns>
public static boolean exist(OLK_EdsEnvironmentId _environmentId)
{
    return _environmentId
        && (select firstonly RecId from OLK_EnvironmentDataSetupTable
                where OLK_EnvironmentDataSetupTable.EnvironmentId == _environmentId).RecId != 0;
}

/// <summary>
/// Finds the master environment.
/// </summary>
/// <returns>The master environment; an empty buffer if none is marked as master.</returns>
public static OLK_EnvironmentDataSetupTable findMaster()
{
    OLK_EnvironmentDataSetupTable environment;

    select firstonly environment
        where environment.MasterEnvironment == NoYes::Yes;

    return environment;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (ret && this.MasterEnvironment)
    {
        OLK_EnvironmentDataSetupTable master;

        select firstonly EnvironmentId from master
            where master.MasterEnvironment == NoYes::Yes
               && master.RecId             != this.RecId;

        if (master.EnvironmentId)
        {
            ret = checkFailed(strFmt("@OLK_EDSLabel:OnlyOneMaster", master.EnvironmentId));
        }
    }

    if (ret)
    {
        ret = this.validateEnvironmentUrl();
    }

    if (ret && this.ClientId && !this.TenantId)
    {
        ret = checkFailed(strFmt("@OLK_EDSLabel:ClientIdEmpty", this.EnvironmentId));
    }

    return ret;
}

/// <summary>
/// The URL is required, must be a valid URL, and no other environment may have the same host name.
/// </summary>
private boolean validateEnvironmentUrl()
{
    OLK_EnvironmentDataSetupTable   other;
    OLK_EdsHostName                 host = OLK_EnvironmentDataSetupKeyManager::normalizeHost(this.EnvironmentUrl);

    if (!this.EnvironmentUrl)
    {
        return checkFailed(strFmt("@OLK_EDSLabel:EnvironmentUrlEmpty", this.EnvironmentId));
    }

    if (!host)
    {
        return checkFailed(strFmt("@OLK_EDSLabel:EnvironmentUrlInvalid", this.EnvironmentUrl));
    }

    while select EnvironmentId, EnvironmentUrl from other
        where other.RecId          != this.RecId
           && other.EnvironmentUrl != ''
    {
        if (OLK_EnvironmentDataSetupKeyManager::normalizeHost(other.EnvironmentUrl) == host)
        {
            return checkFailed(strFmt("@OLK_EDSLabel:EnvironmentUrlUsed", host, other.EnvironmentId));
        }
    }

    if (this.orig().EnvironmentUrl
        && this.KeyFingerprint
        && OLK_EnvironmentDataSetupKeyManager::normalizeHost(this.orig().EnvironmentUrl) != host)
    {
        warning(strFmt("@OLK_EDSLabel:EnvironmentUrlChangedWithKey", this.EnvironmentId));
    }

    return true;
}

/// <summary>
/// Sets the client secret used to call the key service of this environment. It is stored with the platform encryption of
/// the environment where it is entered (normally the master) and is never shown.
/// </summary>
/// <param name = "_set">true when the value is set.</param>
/// <param name = "_secret">The client secret.</param>
/// <returns>A mask when a secret is stored.</returns>
public edit OLK_EdsClientSecret editClientSecret(boolean _set, OLK_EdsClientSecret _secret)
{
    if (_set)
    {
        Global::editEncryptedField(this, _secret, fieldNum(OLK_EnvironmentDataSetupTable, ClientSecret), true);
    }

    return conLen(this.ClientSecret) ? '********' : '';
}

/// <summary>
/// The decrypted client secret, for the token request.
/// </summary>
public str clientSecret()
{
    return conLen(this.ClientSecret)
        ? Global::editEncryptedField(this, '', fieldNum(OLK_EnvironmentDataSetupTable, ClientSecret), false)
        : '';
}

/// <summary>
/// Whether the environment has a key and, when the record describes the current environment, whether it can be unlocked here.
/// </summary>
public display Name keyStatus()
{
    if (!this.KeyFingerprint)
    {
        return "@OLK_EDSLabel:KeyStatusNone";
    }

    if (OLK_EnvironmentDataSetupKeyManager::isCurrentEnvironment(this))
    {
        return OLK_EnvironmentDataSetupKeyManager::canUnlock(this.PublicKey, this.LockedPrivateKey)
            ? "@OLK_EDSLabel:KeyStatusUsable"
            : "@OLK_EDSLabel:KeyStatusNotUnlocked";
    }

    return "@OLK_EDSLabel:KeyStatusEnrolled";
}
